#!/usr/bin/env python3
"""Summarize trial medians; never pool samples from separate native trials."""
import argparse
import collections
import datetime
import hashlib
import json
import math
from pathlib import Path
import re
import statistics

VARIANTS = ("stock-threaded", "overlay-threaded", "overlay-evented", "overlay-kqueue-shared")
WORKLOADS = ("bulk", "echo", "multi-bulk", "multi-echo")
PATTERN = re.compile(r"^(bulk|echo|multi-bulk|multi-echo|warm)-(\d+)-(stock-threaded|overlay-threaded|overlay-evented|overlay-kqueue-shared)\.json$")
COMMON = {
    "schema": "quic-zig-bench-io/3", "zig_version": "0.17.0", "os": "macos",
    "arch": "aarch64", "optimize": "safe", "cpu_count": 32, "leeway_ms": 0,
    "receive_timeout_ms": 5, "receive_batch": 16, "send_batch": 64,
    "tune_socket": False, "offloads": True, "reuse_buffers": True,
}


def digest(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()


def stats(values):
    median = statistics.median(values)
    return {
        "n": len(values), "median": median,
        "mad": statistics.median(abs(x - median) for x in values),
        "min": min(values), "max": max(values), "values": values,
    }


def metric_values(sample):
    result = {k: sample[k] for k in ("wall_ms", "cpu_ms", "cpu_total_ms", "handshake_ms", "client_iterations", "server_iterations")}
    if sample["scenario"] == "goodput":
        result.update(rate_mib_s=sample["mib_per_sec"], cpu_ms_per_mib=sample["cpu_ms_per_mib"],
                      cpu_total_ms_per_mib=sample["cpu_total_ms"] / sample["mib"])
    else:
        result.update(rate_round_trips_s=sample["round_trips_per_sec"],
                      rtt_p50_us=sample["rtt_p50_us"], rtt_p90_us=sample["rtt_p90_us"],
                      rtt_p99_us=sample["rtt_p99_us"], rtt_max_us=sample["rtt_max_us"],
                      cpu_us_per_ping=sample["cpu_ms"] * 1000 / sample["pings"],
                      cpu_total_us_per_ping=sample["cpu_total_ms"] * 1000 / sample["pings"])
    return result


def analyze(directory):
    errors = []
    reports = {}
    manifest = {}
    completion = {"timed": collections.Counter(), "warm": collections.Counter()}
    splits = collections.defaultdict(list)
    trial_rows = []
    command_rows = []
    for path in sorted(directory.glob("*.json")):
        manifest[path.name] = digest(path)
        if path.name.endswith("-commands.json"):
            command_rows.extend(json.loads(path.read_text()))
            continue
        match = PATTERN.match(path.name)
        if not match:
            errors.append(f"Unexpected measurement JSON: {path.name}")
            continue
        workload, trial_text, variant = match.groups()
        trial = int(trial_text)
        report = json.loads(path.read_text())
        reports[(workload, trial, variant)] = report
        group = "warm" if workload == "warm" else "timed"
        completion[group]["reports"] += 1
        for key, expected in COMMON.items():
            if report.get(key) != expected:
                errors.append(f"{path.name}: {key} {report.get(key)!r} != {expected!r}")
        loops, clients = (2, 4) if workload.startswith("multi-") else (1, 1)
        if (report["loops"], report["clients"]) != (loops, clients):
            errors.append(f"{path.name}: wrong loops/clients")
        expected_samples = 2 if workload == "warm" else (1 if workload == "bulk" else 5 if workload == "echo" else 3)
        if len(report["samples"]) != expected_samples:
            errors.append(f"{path.name}: sample count != {expected_samples}")
        scenario_rows = collections.defaultdict(list)
        for index, sample in enumerate(report["samples"]):
            where = f"{path.name}:sample{index + 1}"
            completion[group]["samples"] += 1
            if sample["backend"] != variant.split("-", 1)[1]:
                errors.append(f"{where}: wrong backend")
            if (sample["loops"], sample["clients"]) != (loops, clients):
                errors.append(f"{where}: wrong loops/clients")
            scenario = sample["scenario"]
            if workload != "warm" and scenario != ("goodput" if "bulk" in workload else "echo"):
                errors.append(f"{where}: wrong scenario")
            if scenario == "goodput":
                expected_bytes = report["mib"] * clients * 1024 * 1024
                if sample["delivered_bytes"] != expected_bytes or sample["clean_streams"] != clients:
                    errors.append(f"{where}: byte/clean-FIN completion mismatch")
                if sample["mib"] != report["mib"] * clients or sample["pings"] != 0:
                    errors.append(f"{where}: bulk size/ping mismatch")
                if not math.isclose(sample["cpu_ms_per_mib"], sample["cpu_ms"] / sample["mib"], rel_tol=1e-12):
                    errors.append(f"{where}: CPU/MiB formula mismatch")
                completion[group]["uploads"] += 1
                completion[group]["delivered_bytes"] += sample["delivered_bytes"]
                completion[group]["clean_streams"] += sample["clean_streams"]
            elif scenario == "echo":
                if sample["pings"] != report["pings"] * clients:
                    errors.append(f"{where}: pong count mismatch")
                if sample["delivered_bytes"] != 0 or sample["clean_streams"] != 0:
                    errors.append(f"{where}: unexpected stream data in echo")
                if not 0 < sample["rtt_p50_us"] <= sample["rtt_p90_us"] <= sample["rtt_p99_us"] <= sample["rtt_max_us"]:
                    errors.append(f"{where}: invalid RTT order")
                completion[group]["echo_samples"] += 1
                completion[group]["pongs"] += sample["pings"]
            else:
                errors.append(f"{where}: unknown scenario")
                continue
            values = metric_values(sample)
            if any(not math.isfinite(v) or v < 0 for v in values.values()):
                errors.append(f"{where}: invalid metric")
            scenario_rows[scenario].append(values)
            if loops > 1:
                byte_split, pong_split = sample["server_bytes"], sample["server_datagrams"]
                if len(byte_split) != loops or len(pong_split) != loops:
                    errors.append(f"{where}: wrong split length")
                if sum(byte_split) != sample["delivered_bytes"] or sum(pong_split) != sample["pings"]:
                    errors.append(f"{where}: per-server split total mismatch")
                active = byte_split if scenario == "goodput" else pong_split
                splits[workload].append({"trial": trial, "variant": variant, "sample": index + 1,
                                         "server_bytes": byte_split, "server_datagrams": pong_split,
                                         "active_servers": sum(x != 0 for x in active)})
        for scenario, rows in scenario_rows.items():
            medians = {key: statistics.median(row[key] for row in rows) for key in rows[0]}
            summary = [x for x in report["summaries"] if x["scenario"] == scenario]
            if len(summary) != 1 or summary[0]["samples"] != len(rows):
                errors.append(f"{path.name}: reported summary shape mismatch")
            else:
                checks = {"rate_median": "rate_mib_s" if scenario == "goodput" else "rate_round_trips_s",
                          "cpu_ms_median": "cpu_ms", "handshake_ms_median": "handshake_ms"}
                if scenario == "echo":
                    checks.update(rtt_p50_us_median="rtt_p50_us", rtt_p99_us_median="rtt_p99_us")
                for key, actual_key in checks.items():
                    if not math.isclose(summary[0][key], medians[actual_key], rel_tol=1e-11, abs_tol=1e-8):
                        errors.append(f"{path.name}: reported {key} differs from recomputed median")
            trial_rows.append({"workload": workload, "trial": trial, "variant": variant,
                               "scenario": scenario, "sample_count": len(rows), "medians": medians,
                               "source_file": path.name})
    expected = {(w, i, v) for w in WORKLOADS for i in range(1, 7) for v in VARIANTS}
    expected.update(("warm", 1, v) for v in VARIANTS)
    if set(reports) != expected:
        errors.append(f"Report coverage differs: missing={sorted(expected-set(reports))}; extra={sorted(set(reports)-expected)}")
    for path in sorted(directory.glob("*.log")):
        manifest[path.name] = digest(path)
        text = path.read_text()
        if re.search(r"(?:^|\n)(?:error:|thread .*panic:)", text):
            errors.append(f"Failure marker in {path.name}")
    labels = [c["label"] for c in command_rows]
    if len(labels) != len(set(labels)) or set(labels) != {f"{w}-{i}-{v}" for w, i, v in expected}:
        errors.append("Command/report coverage differs")
    if any(c["exit"] != 0 for c in command_rows):
        errors.append("Nonzero command exit")
    ordered = sorted(command_rows, key=lambda c: c["started"])
    overlaps = [f"{a['label']} -> {b['label']}" for a, b in zip(ordered, ordered[1:]) if b["started"] < a["ended"]]
    if overlaps:
        errors.append(f"Recorded measurement command overlap: {overlaps}")
    binaries = {group: sorted({c["binary_sha256"] for c in command_rows if f"-{group}-" in c["label"]}) for group in ("stock", "overlay")}
    if any(len(hashes) != 1 for hashes in binaries.values()) or binaries["stock"] == binaries["overlay"]:
        errors.append("Expected one distinct binary for stock and one shared overlay binary")
    orders = {}
    for workload in WORKLOADS:
        orders[workload] = [[c["label"].split(f"{workload}-{i}-", 1)[1] for c in ordered if c["label"].startswith(f"{workload}-{i}-")] for i in range(1, 7)]
    by_key = {(r["workload"], r["variant"], r["trial"]): r for r in trial_rows if r["workload"] != "warm"}
    aggregate = {}
    for workload in WORKLOADS:
        aggregate[workload] = {}
        for variant in VARIANTS:
            rows = [by_key[(workload, variant, i)] for i in range(1, 7)]
            aggregate[workload][variant] = {key: stats([r["medians"][key] for r in rows]) for key in rows[0]["medians"]}
    paired = {"same_binary": {}, "stock_control": {}}
    for workload in WORKLOADS:
        paired["same_binary"][workload] = {}
        for variant in ("overlay-evented", "overlay-kqueue-shared", "overlay-threaded"):
            reference = "stock-threaded" if variant == "overlay-threaded" else "overlay-threaded"
            metrics = {}
            for key in aggregate[workload][variant]:
                values = [100 * (by_key[(workload, variant, i)]["medians"][key] / by_key[(workload, reference, i)]["medians"][key] - 1) for i in range(1, 7)]
                metrics[key] = stats(values)
                metrics[key].update(positive_pairs=sum(v > 0 for v in values), negative_pairs=sum(v < 0 for v in values), equal_pairs=sum(v == 0 for v in values),
                                    aggregate_median_ratio_percent=100 * (aggregate[workload][variant][key]["median"] / aggregate[workload][reference][key]["median"] - 1))
            entry = {"reference": reference, "metrics_percent": metrics}
            if variant == "overlay-threaded":
                paired["stock_control"][workload] = entry
            else:
                paired["same_binary"][workload][variant] = entry
    split_summary = {workload: {"samples": len(rows), "all_traffic_on_one_server": all(r["active_servers"] == 1 for r in rows),
                              "active_server_counts": dict(collections.Counter(r["active_servers"] for r in rows)), "records": rows} for workload, rows in splits.items()}
    return {
        "schema": "evented-native-trial-summary/1", "created_utc": datetime.datetime.now(datetime.timezone.utc).isoformat(),
        "input_directory": str(directory), "analysis_script": str(Path(__file__).resolve()), "analysis_script_sha256": digest(Path(__file__)),
        "method": {"trial_reduction": "Median of samples inside each trial, separately for each metric; warmups excluded from performance summaries.",
                   "outer_reduction": "Median and unscaled MAD across six trial medians; min/max are trial-median ranges.",
                   "paired_percent": "100*(variant_trial_median/reference_trial_median-1), then median/MAD/min/max across matched trial IDs.",
                   "tails": "Median of sample p99 values within each trial, then median across trials; not a pooled p99 or percentile of all individual pongs.",
                   "cpu": "Primary CPU metrics use schema cpu_ms transfer/echo window (process user+system, both endpoint loops). cpu_total variants are retained separately.",
                   "outliers": "All six trials retained; no exclusion or claimed causal attribution.",
                   "boundaries": "Native loopback, stock 0.17 compiler with stock/overlay std; not physical NIC line rate, Linux results, or rebuilt-fork compiler proof."},
        "configuration": COMMON, "binary_sha256": binaries, "input_sha256": manifest,
        "integrity": {"pass": not errors, "errors": errors, "completion": {k: dict(v) for k, v in completion.items()},
                      "command_count": len(command_rows), "all_command_exits_zero": all(c["exit"] == 0 for c in command_rows),
                      "recorded_commands_serial": not overlaps, "trial_orders": orders, "per_server": split_summary},
        "trial_medians": trial_rows, "aggregate": aggregate, "paired": paired,
        "observations": [
            "Dispatch single bulk has a small consistent rate decrease and a much larger CPU/MiB increase; multi-peer and echo rate/median-latency regressions are substantial.",
            "Shared Kqueue multi-bulk reduces CPU/MiB in every pair but has materially lower aggregate goodput; this is a tradeoff, not a throughput win.",
            "Shared Kqueue single-bulk trial 5 has unusually low CPU/MiB; it is retained. Other five pairs increase CPU/MiB, and no single-bulk gain is established.",
            "Single-peer p99 ranges overlap with mixed paired direction. Multi-peer Kqueue p99 is worse in every pair; Dispatch multi-peer p99 direction is mixed.",
            "All multi-peer traffic reaches one of the two server sockets in every recorded sample; this does not demonstrate load balancing.",
            "Stock-vs-overlay Threaded comparisons use different binaries and are reported separately; they cannot attribute any difference solely to the std changes.",
        ],
    }


def markdown(data):
    a, p = data["aggregate"], data["paired"]
    def cell(s, digits=2):
        return f"{s['median']:.{digits}f} ± {s['mad']:.{digits}f} [{s['min']:.{digits}f}–{s['max']:.{digits}f}]"
    def delta(s):
        return f"{s['median']:+.1f}% ± {s['mad']:.1f} [{s['min']:+.1f}–{s['max']:+.1f}] ({s['positive_pairs']}+/ {s['negative_pairs']}−/ {s['equal_pairs']}=)"
    lines = ["# Native evented measurement summary", "", "Six matched trials per workload/variant. Values are median ± unscaled MAD [minimum–maximum] of **trial medians**. Bulk has one sample/trial, single echo five, and both multi-peer workloads three. Warmup performance is excluded; its completion is checked.", "", "## Main findings", ""]
    lines.extend("- " + observation for observation in data["observations"])
    lines.extend(["", "## Bulk absolute results", "", "| Workload | Variant | MiB/s | CPU ms/MiB |", "|---|---|---:|---:|"])
    for workload in ("bulk", "multi-bulk"):
        for variant in VARIANTS:
            m = a[workload][variant]
            lines.append(f"| {workload} | {variant} | {cell(m['rate_mib_s'])} | {cell(m['cpu_ms_per_mib'], 3)} |")
    lines.extend(["", "## Echo absolute results", "", "| Workload | Variant | Round trips/s | p50 us | p99 us | CPU us/pong |", "|---|---|---:|---:|---:|---:|"])
    for workload in ("echo", "multi-echo"):
        for variant in VARIANTS:
            m = a[workload][variant]
            lines.append(f"| {workload} | {variant} | {cell(m['rate_round_trips_s'], 0)} | {cell(m['rtt_p50_us'], 1)} | {cell(m['rtt_p99_us'], 1)} | {cell(m['cpu_us_per_ping'], 2)} |")
    lines.extend(["", "## Paired same-binary differences", "", "Reference is overlay Threaded in the same trial. Positive percentages increase the metric: favorable for rate, unfavorable for CPU/latency. Each cell reports paired median ± MAD [min–max], then positive/negative/unchanged pair counts.", "", "| Workload | Variant | Rate change | CPU/unit change | p50 change | p99 change |", "|---|---|---:|---:|---:|---:|"])
    for workload in WORKLOADS:
        for variant in ("overlay-evented", "overlay-kqueue-shared"):
            m = p["same_binary"][workload][variant]["metrics_percent"]
            rate = "rate_mib_s" if "bulk" in workload else "rate_round_trips_s"
            cpu = "cpu_ms_per_mib" if "bulk" in workload else "cpu_us_per_ping"
            lines.append(f"| {workload} | {variant} | {delta(m[rate])} | {delta(m[cpu])} | {delta(m['rtt_p50_us']) if 'rtt_p50_us' in m else '—'} | {delta(m['rtt_p99_us']) if 'rtt_p99_us' in m else '—'} |")
    lines.extend(["", "## Separate stock control", "", "Overlay Threaded relative to stock Threaded; distinct executables. These are controls for binary/std effects, not evented backend comparisons.", "", "| Workload | Rate change | CPU/unit change | p50 change | p99 change |", "|---|---:|---:|---:|---:|"])
    for workload in WORKLOADS:
        m = p["stock_control"][workload]["metrics_percent"]
        rate = "rate_mib_s" if "bulk" in workload else "rate_round_trips_s"
        cpu = "cpu_ms_per_mib" if "bulk" in workload else "cpu_us_per_ping"
        lines.append(f"| {workload} | {delta(m[rate])} | {delta(m[cpu])} | {delta(m['rtt_p50_us']) if 'rtt_p50_us' in m else '—'} | {delta(m['rtt_p99_us']) if 'rtt_p99_us' in m else '—'} |")
    timed, warm = data["integrity"]["completion"]["timed"], data["integrity"]["completion"]["warm"]
    lines.extend(["", "## Completion and provenance", "",
                  f"Integrity checks **{'pass' if data['integrity']['pass'] else 'FAIL'}**. {timed['reports']} timed reports / {timed['samples']} timed samples: {timed['uploads']} uploads, {timed['delivered_bytes']:,} delivered bytes ({timed['delivered_bytes']/1024**3:g} GiB), {timed['clean_streams']} clean streams, and {timed['pongs']:,} pongs. Warmups separately deliver {warm['delivered_bytes']:,} bytes, {warm['clean_streams']} clean streams and {warm['pongs']} pongs across {warm['samples']} samples.", "",
                  f"All {data['integrity']['command_count']} command exits are zero; timestamped commands do not overlap. Every reported sample summary median was independently recomputed. All multi-peer byte/pong split totals match completion; every one of the 144 multi-peer samples places its application traffic on one server socket. The two-loop configuration is not balanced on this native host.", "",
                  "Settings: ReleaseSafe, aarch64 macOS, 32 reported CPUs; receive/send batches 16/64, 5 ms receive timeout, zero Dispatch leeway, reusable buffers, tuning off, offloads on. Single bulk uploads 512 MiB; multi-bulk has four 64 MiB clients over two server loops. Echo has 2,000 pongs/sample single-peer, or four × 1,000 multi-peer.", "",
                  f"Stock binary SHA256: `{data['binary_sha256']['stock'][0]}`. Shared overlay binary SHA256: `{data['binary_sha256']['overlay'][0]}`.", "",
                  "Single-peer tail cells are medians of sample p99s, not pooled p99s. Their ranges overlap and direction is mixed. Multi-peer shared Kqueue p99 increases in all six pairs. No physical-link rate, general application gain, Linux result or rebuilt-compiler release proof follows from these native loopback runs.", "",
                  "### Retained Kqueue single-bulk CPU outlier", ""])
    values = a["bulk"]["overlay-kqueue-shared"]["cpu_ms_per_mib"]["values"]
    lines.append("All six CPU ms/MiB values are retained, in trial order: " + ", ".join(f"{v:.6f}" for v in values) + ". Trial 5 is substantially lower; the other five paired CPU changes are positive. Profiles and independent repetition are needed to explain it; no causal explanation or selective exclusion is applied.")
    lines.extend(["", f"Input directory: `{data['input_directory']}`. Analysis: `{data['analysis_script']}` (SHA256 `{data['analysis_script_sha256']}`). Raw input hashes, trial medians, all metrics including total CPU, paired percentages and per-server splits are retained in `/tmp/evented-native-summary.json`.", ""])
    if data["integrity"]["errors"]:
        lines.extend(["## Integrity failures", "", *["- " + e for e in data["integrity"]["errors"]], ""])
    return "\n".join(lines)


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--input", type=Path, default=Path("/Users/nullstyle/prj/zig/quic-zig/benchmark-reports/evented-2026-10-10/measurements"))
    args = parser.parse_args()
    data = analyze(args.input.resolve())
    Path("/tmp/evented-native-summary.json").write_text(json.dumps(data, indent=2) + "\n")
    Path("/tmp/evented-native-summary.md").write_text(markdown(data))
    print(json.dumps({"integrity": data["integrity"]["pass"], "errors": data["integrity"]["errors"], "completion": data["integrity"]["completion"]}, indent=2))
    raise SystemExit(not data["integrity"]["pass"])


if __name__ == "__main__":
    main()

